sys_variable_value.value:
(function execute(inputs, outputs) {

    var currentRecord = inputs.currentRecord;
    var preenchimentoManual = currentRecord.variables.manual_filling.getValue();

    gs.info('***Contratos Current: ' + currentRecord);
    var tipoLuc = '';

    if(preenchimentoManual == "false"){
        var grLuc = new GlideRecord('x_asscs_allos_informa_es_comerciais_rdl');
        grLuc.addEncodedQuery('sys_id=' + currentRecord.variables.number_contract_v2.getValue());
        grLuc.query();

        if(grLuc.next()){
            tipoLuc = grLuc.tipo_luc;
        }
    }
   


var mrvs = currentRecord.variables.allos_desconto;
var totalRows = mrvs.getRowCount();
var contractPayload = [];

var companyCode = currentRecord.variables.company_code.getDisplayValue();
//var contractNumber = currentRecord.variables.n_contrato_original_crm_sap.getDisplayValue(); //não utilizará esse campo
var contractNumber = currentRecord.variables.local_luc.getDisplayValue() ? currentRecord.variables.local_luc.getDisplayValue() : "Campo vazio";
outputs.errorcontractnumber = contractNumber;


var conditionObj = {
    "CompanyCode": companyCode,
    "ContractNumber": contractNumber,
    "Conditions": []
};

var firstDataInicio = null;
var firstDataFim = null;
//var inconsistentDates = 'false'; // Variável de controle

for (var i = 0; i < totalRows; i++) {
    //if (inconsistentDates == 'true') break; // Para o loop se datas inconsistentes forem encontradas

    var dataInicio = mrvs.getRow(i).getCell('competencia_de').getCellDisplayValue();
    var dataInicioFormatada = formatDateToDDMMYYYY(dataInicio);

    gs.info('***Contratos dataInicio: ' + dataInicio);
    //gs.info('***contrato linha 33 dataInicioFormatada ' + dataInicioFormatada);

    var dataFim = mrvs.getRow(i).getCell('competencia_ate').getCellDisplayValue();
    var dataFimFormatada = formatDateToDDMMYYYY(dataFim);

    //var conditionType = "Z052"; // tornar dinamicamente na V2 com campo (tipo_de_desconto)
    var conditionType = "";

    var tipoDesconto = currentRecord.variables.tipo_de_desconto.getValue()
    var descontoEmDeno =  mrvs.getRow(i).getCell('desconto_em').getCellValue();

    if(tipoDesconto == 'carencia'){
        conditionType = "Z031"; //Z031 Carência reforma
    }else if(tipoDesconto == 'extensao'){
        conditionType = "Z028"; //Z028 Extensão Carência Inauguração
    }else if((tipoDesconto == 'padrao' && tipoLuc == 'LOJA') && (descontoEmDeno != 'e_comuns' && descontoEmDeno != 'fpp')){
        conditionType = "Z052"; // Z052 Desconto Pré - Extraordinário
    }else if(tipoDesconto == 'padrao' && tipoLuc == 'LOJA' && descontoEmDeno == 'e_comuns'){
        conditionType = "Z082"; // Z082 Desconto Encargo
    }else if(tipoDesconto == 'padrao' && tipoLuc == 'LOJA' && descontoEmDeno == 'fpp'){
        conditionType = "Z094"; //Desconto FPP
    }else if((tipoDesconto == 'padrao' && tipoLuc == 'MALL') && (descontoEmDeno == 'e_comuns' && descontoEmDeno != 'fpp')){
        conditionType = "Z282"; //Z282 Desconto Condomínio Mall
    }else if(tipoDesconto == 'padrao' && tipoLuc == 'MALL' &&  descontoEmDeno == 'fpp'){
        conditionType = "Z291"; //Z291 Desconto FPP Mall
    }else if(tipoDesconto == 'padrao' && descontoEmDeno == 'aluguel'){
        conditionType = "Z052"; //Z291 Desconto FPP Mall
    }else {
        conditionType = "Debug não há"; //padrão
    }

    /*if (i === 0) {
        firstDataInicio = dataInicioFormatada;
        firstDataFim = dataFimFormatada;
    } else {
        if (dataInicioFormatada !== firstDataInicio || dataFimFormatada !== firstDataFim) {
            gs.error("Datas inconsistentes: " +
                "\n DataInicio= " + dataInicioFormatada +
                ", \n DataFim= " + dataFimFormatada +
                ". \n Esperado: DataInicio= " + firstDataInicio +
                ", \n DataFim= " + firstDataFim);
            inconsistentDates = 'true'; // Marca a inconsistência
            break; // Interrompe o loop
        }
    }*/

    var opcaoDesconto = mrvs.getRow(i).getCell('opcoes_de_desconto').getCellValue();
    //var percentualValor = mrvs.getRow(i).getCell('valor_desc_readonly').getCellValue();não utlizará mais
    var percentualValor = mrvs.getRow(i).getCell('valor_percentual').getCellValue();
    
   // var fixoValor = mrvs.getRow(i).getCell('valor_de_desconto').getCellValue();
   var fixoValorFinal = mrvs.getRow(i).getCell('valor_percentual_readonly').getCellValue();
   var percentualValorAnswer = '';
    if(percentualValor){
        percentualValorAnswer = percentualValor
    }else {
        var percentualValorAnswer = convertCurrencyToNumber(fixoValorFinal);
    }
    

    var descontoEm = mrvs.getRow(i).getCell('desconto_em').getCellValue();
    gs.info('DESCONTO PK: ' + descontoEm);
    var pontoEquilibrio = mrvs.getRow(i).getCell('ponto_de_equilibrio').getCellValue();
    gs.info('DESCONTO PK PONTO: ' + pontoEquilibrio);

   
    var unitCode = currentRecord.variables.shopping.u_unit_code.getDisplayValue();
    var lucManu = '';
    var lucAuto = '';

    if (currentRecord.variables.luc) {
        lucManu = currentRecord.variables.luc.getDisplayValue();
    }
    if (currentRecord.variables.number_contract_v2) {
        lucAuto = currentRecord.variables.number_contract_v2.getDisplayValue();
    }

    var resultadoLuc = lucAuto && lucAuto.trim() ? lucAuto : lucManu && lucManu.trim() ? lucManu : null;
    var lucKey = companyCode + '/' + unitCode + '/' + resultadoLuc;

    var unitPrice = '';
    if (opcaoDesconto === 'percentual') {
        unitPrice = percentualValor;
    } else if (opcaoDesconto === 'fixo') {
        unitPrice = fixoValorFinal.replace('%', '');
    }

    var regraFaturamento = '';
    if(descontoEm == 'aluguel' && pontoEquilibrio == 'com_desconto'){
        regraFaturamento = '10'
    }else {
        regraFaturamento = '';
    }

    var unitPriceFloat = convertCurrencyToNumber(unitPrice);

    gs.info('***Contratos Unit Price: ' + unitPriceFloat);
    var condition = '';
    if(opcaoDesconto === 'percentual'){
            condition = {
            "ConditionType": conditionType,
            "ValidFrom": dataInicioFormatada,
            "ValidTo": dataFimFormatada,
            "UnitPrice": unitPriceFloat,
            "CalcNorm": "E1",
            "Degrau": false,
            "ExternalPurpose": "A",
            "LucKey": lucKey,
            "DistRule": "A",
            "TermNoSalesRule": regraFaturamento,
            "PercentageOfParticipation": percentualValorAnswer,
            "CalcRuleParameter": "[A   ]"+"[Z010]"+"[IM" + companyCode + unitCode + "     " + resultadoLuc + "]"
        };
    }else if (opcaoDesconto === 'fixo'){
        condition = {
            "ConditionType": conditionType,
            "ValidFrom": dataInicioFormatada,
            "ValidTo": dataFimFormatada,
            "UnitPrice": unitPriceFloat,
            "CalcNorm": "E1",
            "Degrau": false,
            "ExternalPurpose": "A",
            "LucKey": lucKey,
            "DistRule": "A",
            "TermNoSalesRule": regraFaturamento,
            "PercentageOfParticipation": percentualValorAnswer,
            "CalcRuleParameter": "[A   ]"+"[Z010]"+"[IM" + companyCode + unitCode + "     " + resultadoLuc + "]"
        };
    }
   
    conditionObj.Conditions.push(condition);
}

/*if (inconsistentDates == 'false') {
    contractPayload.push(conditionObj);
    gs.info(JSON.stringify(contractPayload).slice(1, -1));
} else {
    gs.error("Execução interrompida devido a datas inconsistentes.");
}*/

function formatDateToDDMMYYYY(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}


function convertCurrencyToNumber(currency) {
    var numberString = currency.replace("R$", "").trim();
    numberString = numberString.replace(",", ".");
    return parseFloat(numberString);
}

    //outputs.datainconsistente = inconsistentDates;
    gs.info('***Contratos Output: ' + JSON.stringify(conditionObj));
    outputs.myobj = JSON.stringify(conditionObj);

})(inputs, outputs);

